package com.skilltargets;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;

/**
 * Maps skills to their component in the skills tab, and back.
 */
final class SkillComponents
{
	private static final Map<Skill, Integer> BY_SKILL = new EnumMap<>(Skill.class);
	private static final Map<Integer, Skill> BY_COMPONENT = new HashMap<>();

	static
	{
		put(Skill.ATTACK, InterfaceID.Stats.ATTACK);
		put(Skill.STRENGTH, InterfaceID.Stats.STRENGTH);
		put(Skill.DEFENCE, InterfaceID.Stats.DEFENCE);
		put(Skill.RANGED, InterfaceID.Stats.RANGED);
		put(Skill.PRAYER, InterfaceID.Stats.PRAYER);
		put(Skill.MAGIC, InterfaceID.Stats.MAGIC);
		put(Skill.RUNECRAFT, InterfaceID.Stats.RUNECRAFT);
		put(Skill.CONSTRUCTION, InterfaceID.Stats.CONSTRUCTION);
		put(Skill.HITPOINTS, InterfaceID.Stats.HITPOINTS);
		put(Skill.AGILITY, InterfaceID.Stats.AGILITY);
		put(Skill.HERBLORE, InterfaceID.Stats.HERBLORE);
		put(Skill.THIEVING, InterfaceID.Stats.THIEVING);
		put(Skill.CRAFTING, InterfaceID.Stats.CRAFTING);
		put(Skill.FLETCHING, InterfaceID.Stats.FLETCHING);
		put(Skill.SLAYER, InterfaceID.Stats.SLAYER);
		put(Skill.HUNTER, InterfaceID.Stats.HUNTER);
		put(Skill.MINING, InterfaceID.Stats.MINING);
		put(Skill.SMITHING, InterfaceID.Stats.SMITHING);
		put(Skill.FISHING, InterfaceID.Stats.FISHING);
		put(Skill.COOKING, InterfaceID.Stats.COOKING);
		put(Skill.FIREMAKING, InterfaceID.Stats.FIREMAKING);
		put(Skill.WOODCUTTING, InterfaceID.Stats.WOODCUTTING);
		put(Skill.FARMING, InterfaceID.Stats.FARMING);
		put(Skill.SAILING, InterfaceID.Stats.SAILING);
	}

	private SkillComponents()
	{
	}

	private static void put(Skill skill, int componentId)
	{
		BY_SKILL.put(skill, componentId);
		BY_COMPONENT.put(componentId, skill);
	}

	static Integer componentFor(Skill skill)
	{
		return BY_SKILL.get(skill);
	}

	static Skill skillFor(int componentId)
	{
		return BY_COMPONENT.get(componentId);
	}
}

package com.skilltargets;

import lombok.Value;
import net.runelite.api.Experience;

/**
 * A target for a single skill. Like RS3, a target is either a level or an XP amount.
 * The XP the skill had when the target was set is kept so progress can be shown
 * from that point rather than from zero.
 */
@Value
class SkillTarget
{
	enum Type
	{
		LEVEL,
		XP
	}

	Type type;
	/**
	 * The target level for {@link Type#LEVEL}, or the target XP for {@link Type#XP}.
	 */
	int value;
	int startXp;

	int getTargetXp()
	{
		return type == Type.LEVEL ? Experience.getXpForLevel(value) : value;
	}

	double getProgress(int currentXp)
	{
		int target = getTargetXp();
		int span = target - startXp;
		if (span <= 0)
		{
			return currentXp >= target ? 1.0 : 0.0;
		}
		return Math.max(0.0, Math.min(1.0, (currentXp - startXp) / (double) span));
	}

	String serialize()
	{
		return type.name() + "," + value + "," + startXp;
	}

	static SkillTarget deserialize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return null;
		}
		try
		{
			String[] parts = s.split(",");
			return new SkillTarget(Type.valueOf(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
		}
		catch (IllegalArgumentException | ArrayIndexOutOfBoundsException e)
		{
			return null;
		}
	}
}

package com.skilltargets;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;

@ConfigGroup(SkillTargetsPlugin.CONFIG_GROUP)
public interface SkillTargetsConfig extends Config
{
	@ConfigItem(
		keyName = "showTargetIcon",
		name = "Show target icon",
		description = "Show a small target icon on skills that have a target",
		position = 1
	)
	default boolean showTargetIcon()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTooltip",
		name = "Add target to tooltip",
		description = "Add target details and a progress bar to the game's skill tooltip",
		position = 2
	)
	default boolean showTooltip()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tooltipBarColor",
		name = "Tooltip bar color",
		description = "Color of the progress bar inside the skill tooltip",
		position = 3
	)
	default Color tooltipBarColor()
	{
		return new Color(0, 200, 0);
	}

	@ConfigItem(
		keyName = "targetReachedNotification",
		name = "Notify on target reached",
		description = "Send a notification when a skill target is reached",
		position = 4
	)
	default Notification targetReachedNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "clearOnReach",
		name = "Clear target when reached",
		description = "Remove the target once it has been reached, like RS3 does",
		position = 5
	)
	default boolean clearOnReach()
	{
		return true;
	}
}

package com.skilltargets;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Rectangle2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class SkillTargetsOverlay extends Overlay
{
	private static final int ICON_SIZE = 9;
	private static final int ICON_MARGIN = 1;
	private static final Color ICON_RED = new Color(200, 30, 30);
	private static final Color ICON_WHITE = new Color(240, 240, 240);
	private static final Color ICON_OUTLINE = Color.BLACK;

	private static final int TOOLTIP_PADDING = 4;
	private static final int TOOLTIP_BAR_HEIGHT = 16;
	private static final Color TOOLTIP_BAR_BORDER = Color.BLACK;
	private static final Color TOOLTIP_BAR_EMPTY = new Color(90, 0, 0);

	private final Client client;
	private final SkillTargetsPlugin plugin;
	private final SkillTargetsConfig config;
	private final SkillTooltipExtender tooltipExtender;

	@Inject
	SkillTargetsOverlay(Client client, SkillTargetsPlugin plugin, SkillTargetsConfig config, SkillTooltipExtender tooltipExtender)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tooltipExtender = tooltipExtender;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<Skill, SkillTarget> targets = plugin.getTargets();
		if (targets.isEmpty())
		{
			return null;
		}

		if (config.showTargetIcon())
		{
			// Overlays draw above all widgets, including the game's skill tooltip. Clip the tooltip's
			// area out so the icons look like they're underneath it.
			Shape previousClip = graphics.getClip();
			Rectangle tooltip = visibleTooltipBounds();
			if (tooltip != null)
			{
				Area clip = new Area(previousClip != null ? previousClip
					: new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));
				clip.subtract(new Area(tooltip));
				graphics.setClip(clip);
			}

			for (Skill skill : targets.keySet())
			{
				Integer componentId = SkillComponents.componentFor(skill);
				Widget widget = componentId == null ? null : client.getWidget(componentId);
				if (widget != null && !widget.isHidden())
				{
					drawTargetIcon(graphics, widget.getBounds());
				}
			}

			graphics.setClip(previousClip);
		}

		drawTooltipBar(graphics);
		return null;
	}

	/**
	 * The area covered by the game's skill tooltip, or null when it isn't showing. The tooltip
	 * component itself is an empty container, so this is the union of its visible pieces.
	 */
	private Rectangle visibleTooltipBounds()
	{
		Widget tooltip = client.getWidget(InterfaceID.Stats.TOOLTIP);
		if (tooltip == null || tooltip.isHidden())
		{
			return null;
		}

		Rectangle union = null;
		for (Widget[] children : new Widget[][]{tooltip.getStaticChildren(), tooltip.getDynamicChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child == null || child.isHidden() || child.getWidth() <= 1 || child.getHeight() <= 1)
				{
					continue;
				}
				Rectangle bounds = child.getBounds();
				union = union == null ? new Rectangle(bounds) : union.union(bounds);
			}
		}
		return union;
	}

	/**
	 * A small red and white bullseye in the top-right corner of the skill, marking that it has a target.
	 */
	private static void drawTargetIcon(Graphics2D graphics, Rectangle bounds)
	{
		int x = bounds.x + bounds.width - ICON_SIZE - ICON_MARGIN;
		int y = bounds.y + ICON_MARGIN;

		Object previous = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		graphics.setColor(ICON_RED);
		graphics.fillOval(x, y, ICON_SIZE, ICON_SIZE);
		graphics.setColor(ICON_WHITE);
		graphics.fillOval(x + 2, y + 2, ICON_SIZE - 4, ICON_SIZE - 4);
		graphics.setColor(ICON_RED);
		graphics.fillOval(x + 3, y + 3, ICON_SIZE - 6, ICON_SIZE - 6);
		graphics.setColor(ICON_OUTLINE);
		graphics.drawOval(x, y, ICON_SIZE - 1, ICON_SIZE - 1);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, previous);
	}

	/**
	 * Draws the progress bar in the row {@link SkillTooltipExtender} reserved at the bottom of the game's tooltip.
	 */
	private void drawTooltipBar(Graphics2D graphics)
	{
		Widget text = tooltipExtender.getExtendedText();
		SkillTarget target = tooltipExtender.getExtendedTarget();
		if (text == null || target == null || text.isHidden())
		{
			return;
		}

		Widget box = text.getParent();
		Rectangle boxBounds = box != null ? box.getBounds() : text.getBounds();

		double progress = target.getProgress(client.getSkillExperience(tooltipExtender.getExtendedSkill()));
		String percent = (int) Math.floor(progress * 100) + "%";

		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = graphics.getFontMetrics();
		int x = boxBounds.x + TOOLTIP_PADDING;
		int width = boxBounds.width - TOOLTIP_PADDING * 2;
		int rowTop = boxBounds.y + boxBounds.height - SkillTooltipExtender.BAR_ROW_HEIGHT - TOOLTIP_PADDING / 2;
		int y = rowTop + (SkillTooltipExtender.BAR_ROW_HEIGHT - TOOLTIP_BAR_HEIGHT) / 2;
		if (width <= 0)
		{
			return;
		}

		graphics.setColor(TOOLTIP_BAR_EMPTY);
		graphics.fillRect(x, y, width, TOOLTIP_BAR_HEIGHT);
		graphics.setColor(config.tooltipBarColor());
		graphics.fillRect(x, y, (int) Math.round(width * progress), TOOLTIP_BAR_HEIGHT);
		graphics.setColor(TOOLTIP_BAR_BORDER);
		graphics.drawRect(x, y, width - 1, TOOLTIP_BAR_HEIGHT - 1);

		// Center on the glyphs' actual drawn height; the font's ascent includes empty space above digits.
		Rectangle2D glyphs = graphics.getFont().createGlyphVector(graphics.getFontRenderContext(), percent).getVisualBounds();
		int textY = (int) Math.round(y + (TOOLTIP_BAR_HEIGHT - glyphs.getHeight()) / 2.0 - glyphs.getY());
		int textX = x + (width - fm.stringWidth(percent)) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(percent, textX + 1, textY + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(percent, textX, textY);
	}
}

package com.skilltargets;

import com.google.inject.Provides;
import java.awt.Color;
import java.text.NumberFormat;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Skill;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Skill Targets",
	description = "Right-click a skill to set an RS3-style level or XP target",
	tags = {"skill", "target", "goal", "xp", "level", "progress", "rs3"}
)
public class SkillTargetsPlugin extends Plugin
{
	static final String CONFIG_GROUP = "skilltargets";
	private static final String TARGET_KEY_PREFIX = "target_";

	private static final String SET_LEVEL_TARGET = "Set level target";
	private static final String SET_XP_TARGET = "Set XP target";
	private static final String CLEAR_TARGET = "Clear target";
	// Same orange the game uses for the skill name in "View <skill> guide".
	private static final Color SKILL_NAME_COLOR = new Color(0xff981f);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SkillTargetsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SkillTargetsOverlay overlay;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Notifier notifier;

	@Inject
	private SkillTooltipExtender tooltipExtender;

	private final Map<Skill, SkillTarget> targets = new EnumMap<>(Skill.class);
	/**
	 * Last XP seen per skill, so "target reached" only fires when the target is crossed.
	 */
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::loadTargets);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		chatboxPanelManager.close();
		tooltipExtender.reset();
		targets.clear();
		lastXp.clear();
	}

	Map<Skill, SkillTarget> getTargets()
	{
		return Collections.unmodifiableMap(targets);
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		lastXp.clear();
		loadTargets();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Each skill in the skills tab has a "View <skill> guide" option; hook our entries in next to it.
		// The skill name is part of the option text and the target is empty, so identify the skill
		// from the component that was right-clicked.
		if (!event.getOption().startsWith("View")
			|| WidgetUtil.componentToInterface(event.getActionParam1()) != InterfaceID.STATS)
		{
			return;
		}

		Skill fromComponent = SkillComponents.skillFor(event.getActionParam1());
		final Skill skill = fromComponent != null ? fromComponent : skillFromOption(event.getOption());
		if (skill == null)
		{
			log.debug("Unknown skill for menu option '{}' on component {}", event.getOption(), event.getActionParam1());
			return;
		}

		// Entries inserted just below the top entry ("View guide") end up directly under it,
		// so insert in reverse of the order they should appear in.
		String target = ColorUtil.wrapWithColorTag(skill.getName(), SKILL_NAME_COLOR);
		if (targets.containsKey(skill))
		{
			addMenuEntry(CLEAR_TARGET, target, () -> clearTarget(skill, true));
		}
		addMenuEntry(SET_XP_TARGET, target, () -> promptXpTarget(skill));
		addMenuEntry(SET_LEVEL_TARGET, target, () -> promptLevelTarget(skill));
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (config.showTooltip() && !targets.isEmpty())
		{
			tooltipExtender.update(targets);
		}
		else
		{
			tooltipExtender.reset();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int xp = event.getXp();
		Integer previous = lastXp.put(skill, xp);

		// Only announce when the target is crossed: not on login (no previous value) and not
		// on every XP drop after a target that wasn't cleared.
		SkillTarget target = targets.get(skill);
		if (target == null || previous == null || previous >= target.getTargetXp() || xp < target.getTargetXp())
		{
			return;
		}

		String what = describe(target);
		sendChatMessage("Congratulations, you've reached your " + skill.getName() + " target of " + what + "!");
		notifier.notify(config.targetReachedNotification(), "You've reached your " + skill.getName() + " target of " + what + "!");

		if (config.clearOnReach())
		{
			clearTarget(skill, false);
		}
	}

	private void addMenuEntry(String option, String target, Runnable onClick)
	{
		int index = client.getMenu().getMenuEntries().length - 1;
		client.getMenu().createMenuEntry(index)
			.setOption(option)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> onClick.run());
	}

	private void promptLevelTarget(Skill skill)
	{
		int currentLevel = Experience.getLevelForXp(client.getSkillExperience(skill));
		if (currentLevel >= Experience.MAX_VIRT_LEVEL)
		{
			sendChatMessage("You can't set a level target for " + skill.getName() + " any higher.");
			return;
		}

		chatboxPanelManager.openTextInput("Set a level target for " + skill.getName()
				+ " (" + (currentLevel + 1) + "-" + Experience.MAX_VIRT_LEVEL + "):")
			.charValidator(Character::isDigit)
			.onDone((String input) -> clientThread.invoke(() -> applyLevelTarget(skill, input)))
			.build();
	}

	private void promptXpTarget(Skill skill)
	{
		int currentXp = client.getSkillExperience(skill);
		if (currentXp >= Experience.MAX_SKILL_XP)
		{
			sendChatMessage("You already have the maximum XP in " + skill.getName() + ".");
			return;
		}

		chatboxPanelManager.openTextInput("Set an XP target for " + skill.getName() + " (e.g. 13034431, 2.5m or 500k):")
			.charValidator(c -> Character.isDigit(c) || c == ',' || c == '.' || c == 'k' || c == 'K' || c == 'm' || c == 'M')
			.onDone((String input) -> clientThread.invoke(() -> applyXpTarget(skill, input)))
			.build();
	}

	private void applyLevelTarget(Skill skill, String input)
	{
		int currentXp = client.getSkillExperience(skill);
		int currentLevel = Experience.getLevelForXp(currentXp);
		int level;
		try
		{
			level = Integer.parseInt(input.trim());
		}
		catch (NumberFormatException e)
		{
			return;
		}

		if (level <= currentLevel || level > Experience.MAX_VIRT_LEVEL)
		{
			sendChatMessage("Your " + skill.getName() + " level target must be between "
				+ (currentLevel + 1) + " and " + Experience.MAX_VIRT_LEVEL + ".");
			return;
		}

		setTarget(skill, new SkillTarget(SkillTarget.Type.LEVEL, level, currentXp));
	}

	private void applyXpTarget(Skill skill, String input)
	{
		int currentXp = client.getSkillExperience(skill);
		Integer xp = parseXp(input);
		if (xp == null)
		{
			return;
		}

		if (xp <= currentXp || xp > Experience.MAX_SKILL_XP)
		{
			sendChatMessage("Your " + skill.getName() + " XP target must be between "
				+ formatNumber(currentXp + 1) + " and " + formatNumber(Experience.MAX_SKILL_XP) + ".");
			return;
		}

		setTarget(skill, new SkillTarget(SkillTarget.Type.XP, xp, currentXp));
	}

	private void setTarget(Skill skill, SkillTarget target)
	{
		targets.put(skill, target);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, TARGET_KEY_PREFIX + skill.name(), target.serialize());
		sendChatMessage("Your " + skill.getName() + " target has been set to " + describe(target) + ".");
	}

	private void clearTarget(Skill skill, boolean announce)
	{
		if (targets.remove(skill) == null)
		{
			return;
		}
		configManager.unsetRSProfileConfiguration(CONFIG_GROUP, TARGET_KEY_PREFIX + skill.name());
		if (announce)
		{
			sendChatMessage("Your " + skill.getName() + " target has been cleared.");
		}
	}

	private void loadTargets()
	{
		targets.clear();
		for (Skill skill : Skill.values())
		{
			SkillTarget target = SkillTarget.deserialize(
				configManager.getRSProfileConfiguration(CONFIG_GROUP, TARGET_KEY_PREFIX + skill.name()));
			if (target != null)
			{
				targets.put(skill, target);
			}
		}
	}

	private void sendChatMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(message)
				.build())
			.build());
	}

	static String describe(SkillTarget target)
	{
		return target.getType() == SkillTarget.Type.LEVEL
			? "level " + target.getValue()
			: formatNumber(target.getValue()) + " XP";
	}

	static String formatNumber(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format(n);
	}

	/**
	 * Gets the skill out of an option like "View &lt;col=ff981f&gt;Strength&lt;/col&gt; guide".
	 */
	private static Skill skillFromOption(String option)
	{
		String name = Text.removeTags(option).replaceFirst("^View ", "").replaceFirst(" guide$", "").trim();
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(name))
			{
				return skill;
			}
		}
		return null;
	}

	/**
	 * Parses "13034431", "13,034,431", "2.5m" or "500k". Returns null when the input isn't a number.
	 */
	static Integer parseXp(String input)
	{
		String s = input.trim().toLowerCase(Locale.US).replace(",", "");
		if (s.isEmpty())
		{
			return null;
		}

		double multiplier = 1;
		char suffix = s.charAt(s.length() - 1);
		if (suffix == 'k' || suffix == 'm')
		{
			multiplier = suffix == 'k' ? 1_000 : 1_000_000;
			s = s.substring(0, s.length() - 1);
		}

		try
		{
			double value = Double.parseDouble(s) * multiplier;
			return value > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) Math.round(value);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	@Provides
	SkillTargetsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SkillTargetsConfig.class);
	}
}

package com.skilltargets;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.FontTypeFace;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * Adds target lines (and room for a progress bar) to the game's own skill tooltip,
 * instead of drawing a second tooltip on top of it.
 */
@Singleton
class SkillTooltipExtender
{
	/**
	 * Height reserved under the text for the progress bar row.
	 */
	static final int BAR_ROW_HEIGHT = 24;
	private static final int FALLBACK_LINE_HEIGHT = 12;
	/**
	 * Minimum space between a label and its value when widening the tooltip.
	 */
	private static final int COLUMN_GAP = 4;
	/**
	 * Safety cap: the longest possible row ("XP to target: 200,000,000") only needs a few digits more.
	 */
	private static final int MAX_WIDTH_GROWTH = 40;
	private static final String MARKER = "Target: ";

	private final Client client;

	/**
	 * The tooltip text widget that was extended this frame, or null. Read by the overlay to place the bar.
	 */
	@Getter
	private Widget extendedText;
	@Getter
	private Skill extendedSkill;
	@Getter
	private SkillTarget extendedTarget;

	/**
	 * What this class last applied to the tooltip. The game can reset the tooltip's size or text on
	 * its own (mouse moves, XP changes), so every frame the current values are compared with these and
	 * anything the game reset is applied again.
	 */
	private static final int UNSET = Integer.MIN_VALUE;
	private int appliedWidth = UNSET;
	private int appliedHeight = UNSET;
	private String appliedValueSuffix;

	@Inject
	SkillTooltipExtender(Client client)
	{
		this.client = client;
	}

	void reset()
	{
		extendedText = null;
		extendedSkill = null;
		extendedTarget = null;
	}

	private void forget()
	{
		appliedWidth = UNSET;
		appliedHeight = UNSET;
		appliedValueSuffix = null;
	}

	/**
	 * Called every frame before the client draws, on the client thread.
	 */
	void update(Map<Skill, SkillTarget> targets)
	{
		reset();

		Widget tooltip = client.getWidget(InterfaceID.Stats.TOOLTIP);
		if (tooltip == null || tooltip.isHidden())
		{
			forget();
			return;
		}

		Skill skill = hoveredSkill();
		SkillTarget target = skill == null ? null : targets.get(skill);
		if (target == null)
		{
			forget();
			return;
		}

		List<Widget> parts = new ArrayList<>();
		collect(tooltip, parts);

		// The game draws the tooltip as two text columns: left-aligned labels ("Strength XP:")
		// and right-aligned values ("2,109,752").
		Widget labels = null;
		Widget values = null;
		for (Widget part : parts)
		{
			if (part.getType() != WidgetType.TEXT || part.getText() == null || part.getText().isEmpty())
			{
				continue;
			}
			if (part.getXTextAlignment() == WidgetTextAlignment.RIGHT)
			{
				values = part;
			}
			else if (labels == null)
			{
				labels = part;
			}
		}

		if (labels == null || values == null)
		{
			forget();
			return;
		}

		apply(tooltip, parts, labels, values, skill, target);

		extendedText = labels;
		extendedSkill = skill;
		extendedTarget = target;
	}

	private void apply(Widget tooltip, List<Widget> parts, Widget labels, Widget values, Skill skill, SkillTarget target)
	{
		int xp = client.getSkillExperience(skill);
		int targetXp = target.getTargetXp();

		List<String> labelLines = new ArrayList<>();
		List<String> valueLines = new ArrayList<>();
		labelLines.add(MARKER);
		valueLines.add(target.getType() == SkillTarget.Type.LEVEL
			? "Level " + target.getValue()
			: SkillTargetsPlugin.formatNumber(targetXp) + " XP");
		if (target.getType() == SkillTarget.Type.LEVEL)
		{
			labelLines.add("Target XP:");
			valueLines.add(SkillTargetsPlugin.formatNumber(targetXp));
		}
		else
		{
			labelLines.add("Level at target:");
			valueLines.add(String.valueOf(Experience.getLevelForXp(targetXp)));
		}
		labelLines.add("XP to target:");
		valueLines.add(SkillTargetsPlugin.formatNumber(Math.max(0, targetXp - xp)));

		boolean changed = false;

		// Text: strip what was added last time (if the game hasn't rewritten it) and add fresh lines.
		String labelSuffix = "<br>" + String.join("<br>", labelLines);
		String valueSuffix = "<br>" + String.join("<br>", valueLines);
		String labelText = labels.getText();
		int cut = labelText.indexOf("<br>" + MARKER);
		String labelBase = cut >= 0 ? labelText.substring(0, cut) : labelText;
		String valueText = values.getText();
		String valueBase = appliedValueSuffix != null && valueText.endsWith(appliedValueSuffix)
			? valueText.substring(0, valueText.length() - appliedValueSuffix.length())
			: valueText;
		if (!labelText.equals(labelBase + labelSuffix))
		{
			labels.setText(labelBase + labelSuffix);
			changed = true;
		}
		if (!valueText.equals(valueBase + valueSuffix))
		{
			values.setText(valueBase + valueSuffix);
			changed = true;
		}
		appliedValueSuffix = valueSuffix;

		// Height: if it isn't what was set last frame, the game reset it; grow from the game's value.
		if (tooltip.getHeightMode() == WidgetSizeMode.ABSOLUTE && tooltip.getOriginalHeight() != appliedHeight)
		{
			int lineHeight = labels.getLineHeight() > 0 ? labels.getLineHeight() : FALLBACK_LINE_HEIGHT;
			appliedHeight = tooltip.getOriginalHeight() + labelLines.size() * lineHeight + BAR_ROW_HEIGHT;
			tooltip.setOriginalHeight(appliedHeight);
			changed = true;
		}

		// Width: same, widening from the game's value only as much as the added rows need.
		if (tooltip.getWidthMode() == WidgetSizeMode.ABSOLUTE && tooltip.getOriginalWidth() != appliedWidth)
		{
			int base = tooltip.getOriginalWidth();
			appliedWidth = base + widthGrowth(tooltip, labels, values, labelLines, valueLines);
			if (appliedWidth != base)
			{
				tooltip.setOriginalWidth(appliedWidth);
				changed = true;
			}
		}

		if (changed)
		{
			revalidate(tooltip, parts);
		}
		// The game may also move the tooltip at any time, so check the edges every frame.
		if (keepOnScreen(tooltip))
		{
			revalidate(tooltip, parts);
		}
	}

	private static void revalidate(Widget tooltip, List<Widget> parts)
	{
		tooltip.revalidate();
		for (Widget part : parts)
		{
			part.revalidate();
		}
	}

	/**
	 * How much wider the tooltip must be for the added rows (e.g. "XP to target:" with a 9 digit
	 * number) to fit next to each other. Zero when they already fit.
	 */
	private static int widthGrowth(Widget tooltip, Widget labels, Widget values, List<String> addedLabels, List<String> addedValues)
	{
		FontTypeFace labelFont = labels.getFont();
		FontTypeFace valueFont = values.getFont();
		if (labelFont == null || valueFont == null)
		{
			return 0;
		}

		int needed = 0;
		for (int i = 0; i < addedLabels.size(); i++)
		{
			needed = Math.max(needed, labelFont.getTextWidth(addedLabels.get(i)) + COLUMN_GAP + valueFont.getTextWidth(addedValues.get(i)));
		}

		// The text columns are sized relative to the tooltip; the difference is the padding around them.
		int inset = tooltip.getWidth() - Math.min(labels.getWidth(), values.getWidth());
		return Math.max(0, Math.min(needed + inset - tooltip.getWidth(), MAX_WIDTH_GROWTH));
	}

	/**
	 * The game places the tooltip for its original size. After growing it, if it now runs past
	 * the right or bottom of the visible area (the skills tab, which on the right column sits
	 * against the RuneLite sidebar), align that edge flush with the area's edge.
	 * Returns true if it was moved.
	 */
	private boolean keepOnScreen(Widget tooltip)
	{
		Widget parent = tooltip.getParent();
		Rectangle area = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		if (parent != null)
		{
			area = area.intersection(parent.getBounds());
		}
		Rectangle box = tooltip.getBounds();
		if (area.isEmpty() || box.isEmpty())
		{
			return false;
		}

		boolean moved = false;
		int overflowX = (box.x + box.width) - (area.x + area.width);
		if (overflowX > 0 && tooltip.getXPositionMode() == WidgetPositionMode.ABSOLUTE_LEFT)
		{
			// Right edge at 0 from the area's right, but never past its left edge.
			tooltip.setOriginalX(tooltip.getOriginalX() - Math.min(overflowX, box.x - area.x));
			moved = true;
		}
		int overflowY = (box.y + box.height) - (area.y + area.height);
		if (overflowY > 0 && tooltip.getYPositionMode() == WidgetPositionMode.ABSOLUTE_TOP)
		{
			tooltip.setOriginalY(tooltip.getOriginalY() - Math.min(overflowY, box.y - area.y));
			moved = true;
		}
		return moved;
	}

	private Skill hoveredSkill()
	{
		Point mouse = client.getMouseCanvasPosition();
		for (Skill skill : Skill.values())
		{
			Integer componentId = SkillComponents.componentFor(skill);
			Widget widget = componentId == null ? null : client.getWidget(componentId);
			if (widget != null && !widget.isHidden() && widget.getBounds().contains(mouse.getX(), mouse.getY()))
			{
				return skill;
			}
		}
		return null;
	}

	private static void collect(Widget widget, List<Widget> out)
	{
		addAll(widget.getStaticChildren(), out);
		addAll(widget.getDynamicChildren(), out);
		addAll(widget.getNestedChildren(), out);
	}

	private static void addAll(Widget[] children, List<Widget> out)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			if (child != null)
			{
				out.add(child);
				collect(child, out);
			}
		}
	}
}

